// numbers are kept as literals so integer fields can be validated exactly.
func newJSONDecoder(raw []byte) *json.Decoder {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	dec.UseNumber()
	return dec
}

