func TestStoreFailuresAre500(t *testing.T) {
	store := newFakeStore()
	store.fail = errors.New("database unavailable")
	h := newHandler(store)

	if rec := do(t, h, http.MethodPost, "/tenants/acme/entitlements", validCreateBody); rec.Code != http.StatusInternalServerError {
