func (in CreateInput) Grant() Grant {
	return Grant{
		Tenant:      in.Tenant,
		GrantID:     in.GrantID,
		Feature:     in.Feature,
		Amount:      in.Amount,
		EffectiveAt: in.EffectiveAt,
		ExpiresAt:   in.ExpiresAt,
		State:       StateActive,
	}
